requestAnimationFrame(frame);
function drawYard(){
  // Floating island shadow and lush lawn slab
  const ground=[[-.25,0,.0],[12.25,0,.0],[12.25,9,.0],[-.25,9,.0]];
  poly(ground,'#4e8d55');
  poly([[0,0,.08],[12,0,.08],[12,9,.08],[0,9,.08]],'#9acb6b');
  // Warm afternoon light
  const sun=ctx.createRadialGradient(W*.76,H*.19,5,W*.76,H*.19,W*.6);sun.addColorStop(0,'#fff2a12b');sun.addColorStop(1,'#fff2a100');ctx.fillStyle=sun;ctx.fillRect(0,0,W,H);
  grass.forEach((g,i)=>{const p=iso(g.x,g.y,.1);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(g.a);ctx.strokeStyle=i%4?'#5c9d574e':'#d6ec9866';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(-2*g.s,0);ctx.quadraticCurveTo(0,-4*g.s,2*g.s,-5*g.s);ctx.stroke();ctx.restore()});
  // Paved path from the house to the emergency phone
  poly([[9.35,6.15,.12],[10.9,6.15,.12],[10.9,7.45,.12],[9.35,7.45,.12]],'#d9b879');
  for(let i=0;i<5;i++){const y=6.3+i*.22;line(9.4,y,10.8,y,'#b8955f88',1)}
  // Back fence, hand painted boards
  for(let x=0;x<=12;x+=.42){poly([[x,0,.12],[x+.33,0,.12],[x+.33,0,.72],[x,0,.72]],x%1<.3?'#8a613d':'#9a7046');line(x,0,x,.72,'#b78d5a',1)}
  line(0,0,12,0,'#684a31',4);line(0,0.22,12,.22,'#745237',3);
  for(let y=.4;y<9;y+=.42){poly([[0,y,.1],[0,y+.32,.1],[0,y+.32,.68],[0,y,.68]],'#916a43');line(0,y,0,y+.7,'#b18a5c',1)}
  line(0,.35,0,8.9,'#694d34',4);
  // Patio slab by the house
  poly([[7.55,.65,.13],[11.65,.65,.13],[11.65,4.1,.13],[7.55,4.1,.13]],'#c5b88d');
  for(let i=0;i<7;i++)line(7.6,.9+i*.47,11.6,.9+i*.47,'#ad9e77aa',1);
  for(let i=0;i<6;i++)line(7.8+i*.65,.7,7.8+i*.65,4.05,'#ad9e7770',1);
  // House, visibly chunky low-poly walls
  poly([[7.7,1.05,.14],[11.2,1.05,.14],[11.2,3.8,.14],[7.7,3.8,.14]],'#f5dfb1');
  poly([[7.7,1.05,.14],[7.7,3.8,.14],[7.7,3.8,2.1],[7.7,1.05,2.1]],'#d7b986');
  poly([[7.7,1.05,2.1],[7.7,3.8,2.1],[9.43,2.43,3.32]],'#c85745');
  poly([[9.43,2.43,3.32],[11.2,1.05,2.1],[11.2,3.8,2.1]],'#a7433d');
  poly([[7.48,1.05,2.02],[9.43,2.43,3.42],[11.4,1.05,2.02],[11.14,.86,2.05],[9.42,2.12,3.18],[7.72,.86,2.05]],'#e17657');
  // Window with shutters
  const win=iso(8.35,1.07,1.08);roundRect(win.x-12*scale/2,win.y-12*scale,24*scale,18*scale,3*scale,'#83c8c0','#f8e6bd');line(8.35,1.07,8.35,1.07,'#fff',1);const wtop=iso(8.35,1.07,1.6);line(8.35,1.07,8.35,1.07,'#fff',1);ctx.strokeStyle='#eef1d1';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(win.x,win.y-8*scale);ctx.lineTo(win.x,win.y+5*scale);ctx.moveTo(win.x-9*scale,win.y-1*scale);ctx.lineTo(win.x+9*scale,win.y-1*scale);ctx.stroke();
  // Back door on front wall
  poly([[9.15,1.04,.15],[10.12,1.04,.15],[10.12,1.04,1.72],[9.15,1.04,1.72]],'#81533b');poly([[9.27,1.025,.18],[10,1.025,.18],[10,1.025,1.6],[9.27,1.025,1.6]],'#a36a43');ellipse(9.86,1.02, .055,.045,'#f1d27b');
  // Cloud puffs and little sun
  const cloud=(x,y,s)=>{const p=iso(x,y,0);ctx.fillStyle='#fff9dcdd';ctx.beginPath();ctx.arc(p.x,p.y,11*s,0,7);ctx.arc(p.x+12*s,p.y-4*s,14*s,0,7);ctx.arc(p.x+26*s,p.y,10*s,0,7);ctx.fill()};cloud(.9,.35,.72);cloud(5.3,.15,.5);
  const sp=iso(11.25,.4,0);ctx.fillStyle='#ffe18b';ctx.beginPath();ctx.arc(sp.x,sp.y,14,0,7);ctx.fill();ctx.strokeStyle='#ffe18b99';ctx.lineWidth=2;for(let i=0;i<8;i++){const a=i*Math.PI/4;ctx.beginPath();ctx.moveTo(sp.x+Math.cos(a)*19,sp.y+Math.sin(a)*19);ctx.lineTo(sp.x+Math.cos(a)*24,sp.y+Math.sin(a)*24);ctx.stroke()}
}
function drawTree(x,y,s=1){ellipse(x,y,.43*s,.24*s,'#447f4c66');poly([[x-.08*s,y,.1],[x+.08*s,y,.1],[x+.08*s,y,1.05*s],[x-.08*s,y,1.05*s]],'#805738');const p=iso(x,y,1.1*s);ctx.fillStyle='#438b50';ctx.beginPath();ctx.arc(p.x,p.y,17*s*scale/40,0,Math.PI*2);ctx.arc(p.x-10*s*scale/40,p.y+5*s*scale/40,12*s*scale/40,0,7);ctx.arc(p.x+10*s*scale/40,p.y+4*s*scale/40,12*s*scale/40,0,7);ctx.fill();ctx.fillStyle='#65a957';ctx.beginPath();ctx.arc(p.x-5*s*scale/40,p.y-4*s*scale/40,7*s*scale/40,0,7);ctx.fill()}
function drawDecor(){
  // Flower clumps and fruit trees outside the path
  drawTree(.8,1.5,.9);drawTree(1.3,7.8,.75);drawTree(11.15,8.1,.95);drawTree(5.9,.65,.75);
  [[1.8,1.2],[3.1,7.8],[6.8,7.9],[11.3,5.2],[5.3,2.3],[1.3,4.1],[6.6,5.2]].forEach((p,i)=>{ellipse(p[0],p[1],.13,.08,'#477b4766');const q=iso(p[0],p[1],.1);ctx.fillStyle=['#f29a70','#f0d56f','#d887ae'][i%3];for(let j=0;j<4;j++){ctx.beginPath();ctx.arc(q.x+Math.cos(j*1.57)*3,q.y+Math.sin(j*1.57)*3,2.2,0,7);ctx.fill()}ctx.fillStyle='#ffe68d';ctx.beginPath();ctx.arc(q.x,q.y,1.7,0,7);ctx.fill()});
  // Picnic table
  ellipse(5.1,2.9,.9,.42,'#507e4c44');poly([[4.35,2.45,.43],[5.8,2.45,.43],[5.8,3.2,.43],[4.35,3.2,.43]],'#99613c');poly([[4.35,2.45,.43],[5.8,2.45,.43],[5.8,3.2,.43],[4.35,3.2,.43]],'#b77a4a');for(const x of [4.52,5.62])for(const y of [2.57,3.08])line(x,y,.12?x:x,.43,'#79503a',2);
  // Grill station
  ellipse(6.4,5.7,.67,.23,'#446f4766');poly([[5.83,5.4,.62],[6.95,5.4,.62],[6.95,5.4,1.18],[5.83,5.4,1.18]],'#34433b');poly([[5.83,5.4,1.18],[6.95,5.4,1.18],[6.95,5.9,1.18],[5.83,5.9,1.18]],'#414f47');poly([[5.83,5.9,.62],[6.95,5.9,.62],[6.95,5.9,1.18],[5.83,5.9,1.18]],'#26342e');line(5.92,5.5,5.92,6.08,'#28342d',3);line(6.85,5.5,6.85,6.08,'#28342d',3);for(let i=0;i<4;i++)line(5.93+i*.29,5.42,5.93+i*.29,5.42,'#ffb762',3);const smoke=iso(6.38,5.58,1.35+Math.sin(elapsed*2)*.08);ctx.fillStyle='#fff7e044';ctx.beginPath();ctx.arc(smoke.x,smoke.y,5,0,7);ctx.arc(smoke.x+5,smoke.y-8,6,0,7);ctx.fill();
  // Plastic chairs
  [[4.05,3.65],[6.08,3.48]].forEach((p,i)=>{poly([[p[0],p[1],.2],[p[0]+.48,p[1],.2],[p[0]+.48,p[1],.67],[p[0],p[1],.67]],i?'#dd6651':'#4c82a0');poly([[p[0],p[1],.66],[p[0]+.48,p[1],.66],[p[0]+.48,p[1]+.38,.66],[p[0],p[1]+.38,.66]],i?'#ef7a60':'#62a6c1');line(p[0]+.08,p[1]+.04,p[0]+.08,p[1]+.44,'#4b4534',2);line(p[0]+.4,p[1]+.04,p[0]+.4,p[1]+.44,'#4b4534',2)});
  // Telephone stand + phone visible at the end of the little path
  const pp=iso(phone.x,phone.y,.18);ellipse(phone.x,phone.y,.5,.24,'#416c4966');poly([[phone.x-.34,phone.y,.18],[phone.x+.34,phone.y,.18],[phone.x+.34,phone.y,.58],[phone.x-.34,phone.y,.58]],'#815735');poly([[phone.x-.4,phone.y-.13,.58],[phone.x+.4,phone.y-.13,.58],[phone.x+.4,phone.y+.13,.58],[phone.x-.4,phone.y+.13,.58]],'#c18a51');
  ctx.save();ctx.translate(pp.x,pp.y-.72*scale);ctx.rotate(-.16);roundRect(-12,-19,24,38,5,'#dc553f','#ffe0aa');roundRect(-8,-14,16,24,3,'#253b35','#ffe0aa');ctx.fillStyle='#c8ff82';for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(-4+i*4,4,1.3,0,7);ctx.fill()}ctx.restore();
  if(collected>=5){const p=iso(phone.x,phone.y,.95);ctx.save();ctx.globalAlpha=.72+.28*Math.sin(elapsed*6);ctx.strokeStyle='#e3ff8c';ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x,p.y-12,23+Math.sin(elapsed*5)*3,0,7);ctx.stroke();ctx.restore();textAt('LIGAR 190',phone.x,phone.y-.2,.7,'#fff9d6',11)}
